// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float32Array( 10 );
	const out = new Float32Array( 2 );

	smeanvarpn(); // $ExpectError
	smeanvarpn( x.length ); // $ExpectError
	smeanvarpn( x.length, 1 ); // $ExpectError
	smeanvarpn( x.length, 1, x ); // $ExpectError
	smeanvarpn( x.length, 1, x, 1 ); // $ExpectError
	smeanvarpn( x.length, 1, x, 1, out ); // $ExpectError
	smeanvarpn( x.length, 1, x, 1, out, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float32Array...
{
	const x = new Float32Array( 10 );
	const out = new Float32Array( 2 );

	smeanvarpn.ndarray( x.length, 1, x, 1, 0, out, 1, 0 ); // $ExpectType Float32Array
}

